MOD = 10 ** 9 + 7

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def distinctSequences(n: int) -> int:
    # Precompute for coprimality: g[i][j] is True if i and j are coprime
    g = [[False] * 7 for _ in range(7)]
    for i in range(1, 7):
        for j in range(1, 7):
            if gcd(i, j) == 1:
                g[i][j] = True

    # Bottom-up DP (iterative, so no recursion-depth problem for n up to 10^4).
    # State: (last roll, roll before it) -> number of valid sequences; 0 means "no roll yet".
    dp = {(0, 0): 1}
    for _ in range(n):
        nxt = {}
        for (prev1, prev2), cnt in dp.items():
            for die in range(1, 7):
                if die != prev1 and die != prev2 and (prev1 == 0 or g[die][prev1]):
                    key = (die, prev1)
                    nxt[key] = (nxt.get(key, 0) + cnt) % MOD
        dp = nxt
    return sum(dp.values()) % MOD
